message.content:
以下是目前可用的所有工具（函式）列表，供您參考與使用：

```json
{
  "activateParkingBrake": {
    "mode": "engage | release"
  },
  "adjustClimateControl": {
    "temperature": "float",
    "unit": "celsius | fahrenheit",
    "fanSpeed": "int 0–100",
    "mode": "auto | cool | heat | defrost"
  },
  "check_tire_pressure": {},
  "displayCarStatus": {
    "option": "fuel | battery | doors | climate | headlights | parkingBrake | brakePedal | engine"
  },
  "display_log": {
    "messages": "string[]"
  },
  "estimate_distance": {
    "cityA": "string",
    "cityB": "string"
  },
  "estimate_drive_feasibility_by_mileage": {
    "distance": "float"
  },
  "find_nearest_tire_shop": {},
  "gallon_to_liter": {
    "gallon": "float"
  },
  "get_current_speed": {},
  "get_outside_temperature_from_google": {},
  "get_outside_temperature_from_weather_com": {},
  "get_zipcode_based_on_city": {
    "city": "string"
  },
  "liter_to_gallon": {
    "liter": "float"
  },
  "lockDoors": {
    "unlock": "boolean",
    "door": "string[] (driver | passenger | rear_left | rear_right)"
  },
  "pressBrakePedal": {
    "pedalPosition": "float 0–1"
  },
  "releaseBrakePedal": {},
  "setCruiseControl": {
    "speed": "float 0–120 (multiple of 5)",
    "activate": "boolean",
    "distanceToNextVehicle": "float"
  },
  "setHeadlights": {
    "mode": "on | off | auto"
  },
  "set_navigation": {
    "destination": "string (street, city, state)"
  },
  "startEngine": {
    "ignitionMode": "START | STOP"
  },
  "fillFuelTank": {
    "fuelAmount": "float"
  }
}
```

如果您想執行其中任何一個功能，只需告訴我具體需求，例如「請把油箱加滿 20 加侖」或「請將氣候控制設定為 22°C」。我會根據您的指示調用相應的工具。
